import heapq

def large_product(list1, list2, n):
    # Sort both lists in descending order to maximize products
    list1.sort(reverse=True)
    list2.sort(reverse=True)

    # Create a max heap to store negative of products (for max heap behavior)
    max_heap = []
    for i in range(len(list1)):
        for j in range(len(list2)):
            product = list1[i] * list2[j]
            if len(max_heap) < n:
                heapq.heappush(max_heap, product)
            else:
                # Only push if the current product is greater than the smallest in the heap
                if product > max_heap[0]:
                    heapq.heappushpop(max_heap, product)
                else:
                    # Since lists are sorted, no need to check further in the inner loop
                    break

    # Extract products from the heap and sort them in descending order
    return sorted(max_heap, reverse=True)

# Example usage
assert large_product([1, 2, 3, 4, 5, 6], [3, 6, 8, 9, 10, 6], 3) == [60, 54, 50]
