def merge_dictionaries_three(dict1, dict2, dict3):
    """
    Merges three dictionaries into one. If there are duplicate keys,
    the value from the dictionary that appears later in the merge will overwrite the earlier ones.
    The order of keys in the result is maintained based on the order they last appear in the input dictionaries.
    """
    from collections import OrderedDict
    merged_dict = OrderedDict()
    for d in (dict1, dict2, dict3):
        merged_dict.update(d)
    return dict(merged_dict)

# Test the function
assert merge_dictionaries_three(
    { "R": "Red", "B": "Black", "P": "Pink" },
    { "G": "Green", "W": "White" },
    { "O": "Orange", "W": "White", "B": "Black" }
) == {'R': 'Red', 'B': 'Black', 'P': 'Pink', 'G': 'Green', 'W': 'White', 'O': 'Orange'}

assert merge_dictionaries_three(
    { "R": "Red", "B": "Black", "P": "Pink" },
    { "G": "Green", "W": "White" },
    {"L": "lavender", "B": "Blue"}
) == {'R': 'Red', 'P': 'Pink', 'G': 'Green', 'W': 'White', 'L': 'lavender', 'B': 'Blue'}
